88	export const getShapeActionPredicates = (
89	  appState: UIAppState,
90	  targetElements: ExcalidrawElement[],
91	  elementsMap: NonDeletedElementsMap | NonDeletedSceneElementsMap,
92	  app: AppClassProperties,
93	) => {
94	  const activeToolType = appState.activeTool.type;
95	
96	  // A property is relevant when it applies to the active tool (so it can be
97	  // preconfigured before drawing) or to any currently selected element.
98	  const forToolOrSelection = (
99	    predicate: (type: ElementOrToolType) => boolean,
100	  ) =>
101	    predicate(activeToolType) ||
102	    targetElements.some((element) => predicate(element.type));
103	
104	  const singleSelected = targetElements.length === 1;
105	
106	  // a container + its bound text read as a single logical element (2 selected)
107	  const isSingleElementBoundContainer =
108	    targetElements.length === 2 &&
109	    (hasBoundTextElement(targetElements[0]) ||
110	      hasBoundTextElement(targetElements[1]));
111	
112	  const isEditingTextOrNewElement = Boolean(
113	    appState.editingTextElement || appState.newElement,
114	  );
115	  const hasSelection = targetElements.length > 0;
116	
117	  return {
118	    /** some element(s) selected */
119	    hasSelection,
120	    /** actions on selected elements (delete/duplicate/...) */
121	    showExtraActions: hasSelection && !isEditingTextOrNewElement,
122	
123	    // color
124	    strokeColor: canChangeStrokeColor(appState, targetElements),
125	    backgroundColor: canChangeBackgroundColor(
